import json

TAX = 1.24


def load(path="items.json"):
    with open(path) as f:
        return json.load(f)


def total(items):
    subtotal = sum(item["price"] for item in items) * TAX
    return subtotal * TAX


if __name__ == "__main__":
    items = load()
    for item in items:
        print(f"{item['name']:<10} {item['price']:6.2f}")
    print(f"{'Total':<10} {total(items):6.2f}")

